import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Phase 6 · Multi-device and Long-running Operation","description":"Let the same tasks, memory, and authority run safely across devices over the long term.","frontmatter":{"title":"Phase 6 · Multi-device and Long-running Operation","description":"Let the same tasks, memory, and authority run safely across devices over the long term.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-6.md","filePath":"en/delivery/stage-6.md","lastUpdated":1794017073000}'),i={name:"en/delivery/stage-6.md"};function s(r,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-6-·-multi-device-and-long-running-operation" tabindex="-1">Phase 6 · Multi-device and Long-running Operation <a class="header-anchor" href="#phase-6-·-multi-device-and-long-running-operation" aria-label="Permalink to &quot;Phase 6 · Multi-device and Long-running Operation&quot;">​</a></h1><p>See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 Delivery Status</a> for implemented scope, verified paths, and deliberate gaps.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented code loop:</strong> Incremental event sync with conflict choice, task leases and epoch fencing, device revocation and token rotation, kill switch, encrypted backup and restore, health checks, maintenance, and redacted diagnostics. The connection runtime separates transport, subscription, data freshness, and execution ownership, with generation isolation, an offline outbox, and cached projections.</li><li><strong>Still open:</strong> Real remote nodes and phones, real offline reconnect and cross-node outbox reconciliation, two real devices switching, a lost-device drill, full migration, multi-week continuous operation, and v1.0 release acceptance. See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 delivery status</a>.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 6 expands the single-device product into a Personal Agent OS that runs for the long term, stays consistent across devices, can be backed up, migrated, and revoked. Multi-device does not mean copying multiple agents; it means the same tasks, memory, and authority continue on different devices.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-6/6-1.html">6.1 Sync and switch across devices</a></td><td>Keep the same tasks and artifacts consistent across devices.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/6-2.html">6.2 Revoke devices and migrate safely</a></td><td>A lost device can be disabled immediately, and data moves fully when replacing it.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/6-3.html">6.3 Back up, restore, and upgrade</a></td><td>Changing machines, versions, or making a mistake does not lose tasks, artifacts, or memory.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-6/6-4.html">6.4 Long-running operation and v1.0 acceptance</a></td><td>Run stably for the long term, then release v1.0 after full acceptance.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>First make tasks and artifacts consistent across devices.</li><li>Then handle offline use, device switching, and capability routing.</li><li>Then complete device revocation, backup, restore, and upgrade.</li><li>Finally run the long-term test and full acceptance for v1.0.</li></ol>',10)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
